fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Iterate over the array in reverse to find the last occurrence
    for i in (0..cafes.len()).rev() {
        if cafes[i] == cafe {
            return i; // Return the index of the last occurrence
        }
    }
    // If the cafe is not found, return the length of the array (should not happen in this context)
    cafes.len()
}

fn solve(cafes: Vec<i8>) -> i8 {
    let mut min_last_occurrence = usize::MAX; // Initialize to maximum possible value
    let mut result = cafes[0]; // Start with the first element as the result

    // Iterate through each unique value in the cafes array
    for &cafe in &cafes {
        let last_occurrence = exec_last_occurrence_position(&cafes, cafe);
        // Check if this last occurrence is less than the current minimum
        if last_occurrence < min_last_occurrence {
            min_last_occurrence = last_occurrence; // Update minimum last occurrence
            result = cafe; // Update result to the current cafe
        }
    }

    result // Return the cafe with the minimal last occurrence position
}